ReplacementChunks.ReplacementContent:
let cursor_row_in_viewport =
    sb.cursor.map(|c| c.1 as isize + sb.viewport_offset as isize).unwrap_or(-1);
let cursor = if pane_id == active_pane_id
    && cursor_row_in_viewport >= 0 && cursor_row_in_viewport < sb.grid.len() as isize
{
    Some((sb.cursor.unwrap().0, cursor_row_in_viewport as usize))
} else {
    None
};

ReplacementChunks.TargetContent:
let cursor_row_in_viewport =
    sb.cursor.row as isize + sb.scroll_offset as isize;
let cursor = if pane_id == active_pane_id
    && cursor_row_in_viewport < sb.rows() as isize
{
    Some((sb.cursor.col, cursor_row_in_viewport as usize))
} else {
    None
};
